// symbol    ?compute_lighting_table@MapWin@@SAXXZ
void MapWin::compute_lighting_table() {
    int x;
    int y;
    for (int quadrant = 0; quadrant < 4; ++quadrant) {
        for (int i = 1; i < 8; ++i) {
            for (int j = 1; j < 8; ++j) {
                switch (quadrant) {
                case 0:
                    x = i - 4;
                    y = j - 4;
                    break;
                case 1:
                    x = 4 - j;
                    y = i - 4;
                    break;
                case 2:
                    x = 4 - i;
                    y = 4 - j;
                    break;
                case 3:
                    x = j - 4;
                    y = 4 - i;
                    break;
                }
                x *= 100;
                y *= 100;
                const int root = quick_root(y * y + x * x);
                int light = -3 * (x + y);
                if (root != 0) {
                    light /= root;
                }
                MapLightingTable[quadrant * 49 + i * 7 + j - 8] = static_cast<signed char>(light);
            }
        }
    }
}

